  final String codigo;
  final String? fincaId;
  final String variedad;
  final DateTime? fechaCosecha;
  final DateTime fechaLlegada;
  final EstadoLote estado;
  final String notas;

  /// Motivo si se saltó una etapa obligatoria (RF-LOT-03).
  final String motivoSalto;

  /// Queda bloqueado para venta si el cadmio supera el límite (RN-15).
  final bool ventaBloqueada;
  final String motivoBloqueo;
  const Lote({
    required this.id,
    required this.creadoEn,
    required this.modificadoEn,
