    map['mazorcas_sanas'] = Variable<int>(mazorcasSanas);
    map['mazorcas_monilia'] = Variable<int>(mazorcasMonilia);
    map['mazorcas_fitoftora'] = Variable<int>(mazorcasFitoftora);
    map['mazorcas_otro'] = Variable<int>(mazorcasOtro);
    map['mazorcas_descartadas'] = Variable<int>(mazorcasDescartadas);
    map['motivo_descarte'] = Variable<String>(motivoDescarte);
    map['dias_reposo'] = Variable<int>(diasReposo);
    if (!nullToAbsent || fechaAperturaPlan != null) {
      map['fecha_apertura_plan'] = Variable<DateTime>(fechaAperturaPlan);
