class PruebaCorte extends DataClass implements Insertable<PruebaCorte> {
  final String id;
  final DateTime creadoEn;
  final DateTime modificadoEn;
  final String usuarioId;
  final String dispositivoId;
  final EstadoSync estadoSync;
  final bool eliminado;
  final String loteId;
  final DateTime fecha;
  final String perfilNorma;
  final int granos;

  /// Conteo por clase, como JSON: {"bien_fermentado": 70, ...}
  final String conteosJson;

  /// Porcentajes calculados, como JSON. Se guardan para no recalcularlos y
  /// para que el reporte muestre exactamente lo que vio el usuario ese día.
  final String porcentajesJson;
  final String resultado;
  final bool conforme;
  final double? peso100g;

  /// Versión del modelo M2 que se usó, o vacío si fue conteo manual (RF-IA-05).
  final String modeloVersion;

  /// Si es una prueba parcial del día 5 con menos de 100 granos (RF-FER-06).
  final bool esParcial;
  final String? fotoId;
  const PruebaCorte({
    required this.id,
    required this.creadoEn,
    required this.modificadoEn,
    required this.usuarioId,
    required this.dispositivoId,
    required this.estadoSync,
    required this.eliminado,
    required this.loteId,
    required this.fecha,
    required this.perfilNorma,
    required this.granos,
    required this.conteosJson,
    required this.porcentajesJson,
    required this.resultado,
    required this.conforme,
    this.peso100g,
    required this.modeloVersion,
    required this.esParcial,
    this.fotoId,
  });
