  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['creado_en'] = Variable<DateTime>(creadoEn);
    map['modificado_en'] = Variable<DateTime>(modificadoEn);
    map['usuario_id'] = Variable<String>(usuarioId);
    map['dispositivo_id'] = Variable<String>(dispositivoId);
    {
      map['estado_sync'] = Variable<int>(
        $PruebasCorteTable.$converterestadoSync.toSql(estadoSync),
      );
    }
    map['eliminado'] = Variable<bool>(eliminado);
    map['lote_id'] = Variable<String>(loteId);
    map['fecha'] = Variable<DateTime>(fecha);
    map['perfil_norma'] = Variable<String>(perfilNorma);
    map['granos'] = Variable<int>(granos);
    map['conteos_json'] = Variable<String>(conteosJson);
    map['porcentajes_json'] = Variable<String>(porcentajesJson);
    map['resultado'] = Variable<String>(resultado);
    map['conforme'] = Variable<bool>(conforme);
    if (!nullToAbsent || peso100g != null) {
      map['peso100g'] = Variable<double>(peso100g);
    }
    map['modelo_version'] = Variable<String>(modeloVersion);
    map['es_parcial'] = Variable<bool>(esParcial);
    if (!nullToAbsent || fotoId != null) {
      map['foto_id'] = Variable<String>(fotoId);
    }
    return map;
  }

  PruebasCorteCompanion toCompanion(bool nullToAbsent) {
    return PruebasCorteCompanion(
      id: Value(id),
