class Tostado extends DataClass implements Insertable<Tostado> {
  final String id;
  final DateTime creadoEn;
  final DateTime modificadoEn;
  final String usuarioId;
  final String dispositivoId;
  final EstadoSync estadoSync;
  final bool eliminado;
  final String loteProduccionId;
  final String? equipoId;
  final DateTime fecha;
  final double kgEntrada;
  final double? kgSalida;

  /// Perfil por tramos, como JSON: [{"minutos":10,"tempC":140}, ...]
  final String perfilJson;
  final double? tempC;
  final int? minutos;

  /// Grado que estimó el modelo M3, si está instalado (RF-TOS-03).
  final String gradoIa;
  final double? confianzaIa;

  /// Lo que dijo el usuario. Si difiere de la IA, manda esto (RF-IA-03).
  final String gradoUsuario;
  final String modeloVersion;
  final String? fotoId;

  /// Nombre de la receta de tostado guardada, para comparar lotes (RF-TOS-05).
  final String recetaNombre;
  const Tostado({
    required this.id,
    required this.creadoEn,
    required this.modificadoEn,
    required this.usuarioId,
    required this.dispositivoId,
    required this.estadoSync,
    required this.eliminado,
    required this.loteProduccionId,
    this.equipoId,
    required this.fecha,
    required this.kgEntrada,
    this.kgSalida,
    required this.perfilJson,
    this.tempC,
    this.minutos,
    required this.gradoIa,
    this.confianzaIa,
    required this.gradoUsuario,
    required this.modeloVersion,
    this.fotoId,
    required this.recetaNombre,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['creado_en'] = Variable<DateTime>(creadoEn);
    map['modificado_en'] = Variable<DateTime>(modificadoEn);
    map['usuario_id'] = Variable<String>(usuarioId);
    map['dispositivo_id'] = Variable<String>(dispositivoId);
    {
      map['estado_sync'] = Variable<int>(
        $TostadosTable.$converterestadoSync.toSql(estadoSync),
      );
    }
    map['eliminado'] = Variable<bool>(eliminado);
    map['lote_produccion_id'] = Variable<String>(loteProduccionId);
    if (!nullToAbsent || equipoId != null) {
      map['equipo_id'] = Variable<String>(equipoId);
    }
    map['fecha'] = Variable<DateTime>(fecha);
    map['kg_entrada'] = Variable<double>(kgEntrada);
    if (!nullToAbsent || kgSalida != null) {
      map['kg_salida'] = Variable<double>(kgSalida);
