      map['lote_produccion_id'] = Variable<String>(loteProduccionId.value);
    }
    if (fecha.present) {
      map['fecha'] = Variable<DateTime>(fecha.value);
    }
    if (kgNibs.present) {
      map['kg_nibs'] = Variable<double>(kgNibs.value);
    }
    if (kgCascarilla.present) {
      map['kg_cascarilla'] = Variable<double>(kgCascarilla.value);
    }
    if (notas.present) {
      map['notas'] = Variable<String>(notas.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('DescascarilladosCompanion(')
          ..write('id: $id, ')
          ..write('creadoEn: $creadoEn, ')
          ..write('modificadoEn: $modificadoEn, ')
          ..write('usuarioId: $usuarioId, ')
          ..write('dispositivoId: $dispositivoId, ')
          ..write('estadoSync: $estadoSync, ')
          ..write('eliminado: $eliminado, ')
          ..write('loteProduccionId: $loteProduccionId, ')
          ..write('fecha: $fecha, ')
          ..write('kgNibs: $kgNibs, ')
          ..write('kgCascarilla: $kgCascarilla, ')
          ..write('notas: $notas, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

