class Refinado extends DataClass implements Insertable<Refinado> {
  final String id;
  final DateTime creadoEn;
  final DateTime modificadoEn;
  final String usuarioId;
  final String dispositivoId;
  final EstadoSync estadoSync;
  final bool eliminado;
  final String loteProduccionId;
  final DateTime inicio;
  final DateTime? fin;
  final double? horas;
  final double nibsKg;
  final double azucarKg;
  final double mantecaKg;
  final double lecitinaKg;
  final DateTime? momentoAzucar;
  final double? tempC;

  /// Evaluación sensorial 1-5, como JSON:
  /// {"acidez":2,"amargor":4,"astringencia":2,"textura":5}
  final String sensorialJson;
  final String notas;
  const Refinado({
    required this.id,
    required this.creadoEn,
    required this.modificadoEn,
    required this.usuarioId,
    required this.dispositivoId,
    required this.estadoSync,
    required this.eliminado,
    required this.loteProduccionId,
    required this.inicio,
    this.fin,
    this.horas,
    required this.nibsKg,
    required this.azucarKg,
    required this.mantecaKg,
    required this.lecitinaKg,
    this.momentoAzucar,
    this.tempC,
    required this.sensorialJson,
    required this.notas,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['creado_en'] = Variable<DateTime>(creadoEn);
    map['modificado_en'] = Variable<DateTime>(modificadoEn);
    map['usuario_id'] = Variable<String>(usuarioId);
    map['dispositivo_id'] = Variable<String>(dispositivoId);
    {
      map['estado_sync'] = Variable<int>(
        $RefinadosTable.$converterestadoSync.toSql(estadoSync),
      );
    }
    map['eliminado'] = Variable<bool>(eliminado);
    map['lote_produccion_id'] = Variable<String>(loteProduccionId);
    map['inicio'] = Variable<DateTime>(inicio);
    if (!nullToAbsent || fin != null) {
      map['fin'] = Variable<DateTime>(fin);
    }
    if (!nullToAbsent || horas != null) {
      map['horas'] = Variable<double>(horas);
    }
    map['nibs_kg'] = Variable<double>(nibsKg);
    map['azucar_kg'] = Variable<double>(azucarKg);
    map['manteca_kg'] = Variable<double>(mantecaKg);
    map['lecitina_kg'] = Variable<double>(lecitinaKg);
    if (!nullToAbsent || momentoAzucar != null) {
      map['momento_azucar'] = Variable<DateTime>(momentoAzucar);
    }
    if (!nullToAbsent || tempC != null) {
      map['temp_c'] = Variable<double>(tempC);
    }
    map['sensorial_json'] = Variable<String>(sensorialJson);
    map['notas'] = Variable<String>(notas);
    return map;
  }

  RefinadosCompanion toCompanion(bool nullToAbsent) {
    return RefinadosCompanion(
      id: Value(id),
      creadoEn: Value(creadoEn),
      modificadoEn: Value(modificadoEn),
