  final String tempsJson;
  final double? tempCuarto;
  final double? hrCuarto;

  /// Prueba del papel: ¿endureció con brillo en ~3 minutos? (RF-ATE-03)
  final bool? pruebaPapel;

  /// Resultado del modelo M4 sobre la foto de las barras (RF-ATE-04).
  final String resultadoIa;
  final double? confianzaIa;
  final String resultadoUsuario;
  final String modeloVersion;
  final String? fotoId;

