    map['resultado_ia'] = Variable<String>(resultadoIa);
    if (!nullToAbsent || confianzaIa != null) {
      map['confianza_ia'] = Variable<double>(confianzaIa);
    }
    map['resultado_usuario'] = Variable<String>(resultadoUsuario);
    map['modelo_version'] = Variable<String>(modeloVersion);
    if (!nullToAbsent || fotoId != null) {
      map['foto_id'] = Variable<String>(fotoId);
    }
    if (!nullToAbsent || diasInspeccion != null) {
      map['dias_inspeccion'] = Variable<int>(diasInspeccion);
    }
    return map;
