class Foto extends DataClass implements Insertable<Foto> {
  final String id;
  final DateTime creadoEn;
  final DateTime modificadoEn;
  final String usuarioId;
  final String dispositivoId;
  final EstadoSync estadoSync;
  final bool eliminado;

  /// Ruta en la carpeta privada de la app.
  final String rutaLocal;
  final String rutaMiniatura;

  /// Identificador del archivo en Google Drive, cuando ya se subió.
  final String driveFileId;
  final String etapa;
  final String? loteId;
  final String? loteProduccionId;

  /// Lo que dijo el modelo, como JSON: {"clase":"monilia","confianza":0.83}
  final String analisisIaJson;

  /// Lo que dijo el usuario. Si está puesto, manda sobre la IA (RF-IA-03).
  final String etiquetaUsuario;

  /// Si sirve para reentrenar: el usuario la revisó y la etiqueta es de fiar
  /// (RF-PRC-09, §8.3 de la ERS).
  final bool aptaDataset;
  final double? latitud;
  final double? longitud;
  const Foto({
    required this.id,
    required this.creadoEn,
    required this.modificadoEn,
    required this.usuarioId,
    required this.dispositivoId,
    required this.estadoSync,
    required this.eliminado,
    required this.rutaLocal,
    required this.rutaMiniatura,
    required this.driveFileId,
    required this.etapa,
    this.loteId,
    this.loteProduccionId,
    required this.analisisIaJson,
    required this.etiquetaUsuario,
    required this.aptaDataset,
    this.latitud,
    this.longitud,
  });
