    map['dispositivo_id'] = Variable<String>(dispositivoId);
    {
      map['estado_sync'] = Variable<int>(
        $FotosTable.$converterestadoSync.toSql(estadoSync),
      );
    }
    map['eliminado'] = Variable<bool>(eliminado);
    map['ruta_local'] = Variable<String>(rutaLocal);
    map['ruta_miniatura'] = Variable<String>(rutaMiniatura);
    map['drive_file_id'] = Variable<String>(driveFileId);
    map['etapa'] = Variable<String>(etapa);
    if (!nullToAbsent || loteId != null) {
      map['lote_id'] = Variable<String>(loteId);
    }
    if (!nullToAbsent || loteProduccionId != null) {
      map['lote_produccion_id'] = Variable<String>(loteProduccionId);
    }
    map['analisis_ia_json'] = Variable<String>(analisisIaJson);
    map['etiqueta_usuario'] = Variable<String>(etiquetaUsuario);
    map['apta_dataset'] = Variable<bool>(aptaDataset);
    if (!nullToAbsent || latitud != null) {
      map['latitud'] = Variable<double>(latitud);
