class OperacionSync extends DataClass implements Insertable<OperacionSync> {
  final String id;
  final String tabla;
  final String registroId;

  /// `crear`, `actualizar`, `eliminar`, `subir_foto`.
  final String operacion;

  /// Copia del registro en el momento de encolar, como JSON.
  final String cargaJson;
  final DateTime creadoEn;
  final int intentos;
  final DateTime? proximoIntento;
  final String ultimoError;

  /// Las fotos solo se suben con WiFi si el usuario dejó activa esa opción
  /// (RF-SYN-04), así que la cola necesita saber si esta operación es pesada.
  final bool esArchivo;
  const OperacionSync({
    required this.id,
    required this.tabla,
    required this.registroId,
    required this.operacion,
    required this.cargaJson,
