    map['registro_id'] = Variable<String>(registroId);
    map['operacion'] = Variable<String>(operacion);
    map['carga_json'] = Variable<String>(cargaJson);
    map['creado_en'] = Variable<DateTime>(creadoEn);
    map['intentos'] = Variable<int>(intentos);
    if (!nullToAbsent || proximoIntento != null) {
      map['proximo_intento'] = Variable<DateTime>(proximoIntento);
    }
    map['ultimo_error'] = Variable<String>(ultimoError);
    map['es_archivo'] = Variable<bool>(esArchivo);
    return map;
  }

  ColaSyncCompanion toCompanion(bool nullToAbsent) {
    return ColaSyncCompanion(
      id: Value(id),
      tabla: Value(tabla),
      registroId: Value(registroId),
      operacion: Value(operacion),
      cargaJson: Value(cargaJson),
      creadoEn: Value(creadoEn),
      intentos: Value(intentos),
      proximoIntento: proximoIntento == null && nullToAbsent
          ? const Value.absent()
          : Value(proximoIntento),
      ultimoError: Value(ultimoError),
      esArchivo: Value(esArchivo),
    );
  }

